-- what-is-a-cooling-tower-types-and-how-it-works
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2604-3333-4333-8333-cccccccc2604', 'cccc2604-1111-4111-8111-cccccccc2604', 'en', 'Cooling Tower Basics: Types, Working Principle, Losses, and Design Parameters', 'what-is-a-cooling-tower-types-and-how-it-works', JSON_OBJECT('html', '<h2>What Is a Cooling Tower?</h2><p>A cooling tower is a <strong>heat rejection</strong> device that removes heat from warm process or HVAC water and releases it to the atmosphere. A small portion of water evaporates and carries away heat. The cooled water is collected in a basin and returned to the system.</p><h2>How It Works</h2><ol><li><strong>Distribution:</strong> warm water is distributed over fill media.</li><li><strong>Surface area:</strong> film/droplet formation increases heat transfer area.</li><li><strong>Airflow:</strong> fan (or natural draft) moves air through wetted surfaces.</li><li><strong>Heat transfer:</strong> sensible + <em>partial evaporation</em> cools the water.</li><li><strong>Collection:</strong> cooled water returns to the loop.</li></ol><h2>Counterflow vs Crossflow</h2><p><strong>Counterflow</strong>: air moves upward while water moves downward. <strong>Crossflow</strong>: air moves horizontally/diagonally relative to falling water.</p><h2>Open vs Closed Circuit</h2><p><strong>Open circuit</strong> towers directly expose process water to air. <strong>Closed circuit</strong> towers keep process fluid inside a coil while spray water + air reject heat.</p><h2>Key Design Metrics</h2><ul><li><strong>Range:</strong> hot-water inlet minus cold-water outlet.</li><li><strong>Approach:</strong> cold-water outlet minus <em>wet-bulb</em> temperature.</li><li><strong>Wet-bulb:</strong> practical performance limit for evaporative cooling.</li></ul><h2>Water Losses</h2><ul><li><strong>Evaporation:</strong> inherent heat removal mechanism.</li><li><strong>Drift:</strong> droplets carried out with exhaust air; reduced by drift eliminators.</li><li><strong>Blowdown:</strong> controlled purge to manage dissolved solids (TDS).</li></ul><h2>Operation and Maintenance</h2><ul><li>Water treatment (scale/corrosion/biological control) is essential.</li><li>Periodic inspections: nozzles, fill, drift eliminators, fan/motor group, basin hygiene.</li></ul>'), 'Cooling tower working principle, classifications, key design parameters, and operating losses.', 'Cooling tower technical article image', 'Cooling tower basics', 'Cooling tower working principle, classifications, key design parameters, and operating losses.', 'cooling tower, counterflow, crossflow, drift, blowdown', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- features-of-ensotek-cooling-towers
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2605-3333-4333-8333-cccccccc2605', 'cccc2605-1111-4111-8111-cccccccc2605', 'en', 'Features of Ensotek Cooling Towers', 'features-of-ensotek-cooling-towers', JSON_OBJECT('html', '<h2>Features of Ensotek Cooling Towers</h2><h3>Body and Material Structure</h3><ul><li><strong>GRP body:</strong> Ensotek cooling towers are made of fiberglass reinforced polyester (GRP), so painting is not required. The structure remains corrosion-resistant over long service life.</li><li><strong>Chemical/corrosion resistance:</strong> GRP offers strong resistance to chemicals and corrosion compared to conventional metal constructions.</li><li><strong>Flame-retardant resin option:</strong> For sensitive facilities (hotels, hospitals, malls, residences), a flame-retardant resin can be selected to improve fire safety.</li></ul><h3>Fill Options</h3><p>Depending on water quality and operating conditions, the following fill types may be used:</p><ol><li><strong>PVC film fill:</strong> for clean circulating water; high wetted surface area supports strong thermal performance.</li><li><strong>PP splash fill (bigudi type):</strong> preferred for dirty/oily water and dusty environments; lower clogging risk, often washable and reusable; PP can withstand high temperatures (around 100°C).</li><li><strong>PP grid splash fill:</strong> for very dirty water where maintainability and clogging resistance are critical.</li></ol><h3>Durability and Operating Economy</h3><ul><li><strong>Long service life:</strong> composite construction reduces corrosion-related deterioration.</li><li><strong>Lower maintenance cost:</strong> GRP body and correct fill selection help reduce routine maintenance.</li></ul><h3>Fan Configuration and Energy Efficiency</h3><ul><li><strong>Top-mounted induced-draft, counterflow design:</strong> airflow management can reduce recirculation of moist discharge air.</li><li><strong>Energy advantage:</strong> under suitable conditions, induced-draft designs can be more energy-efficient than forced-draft layouts.</li></ul><h3>Performance and Operational Advantages</h3><ul><li><strong>High cooling performance:</strong> improved approach to wet-bulb can support stable processes and energy savings.</li><li><strong>Total cost of ownership:</strong> lifecycle economics may be optimized through reduced maintenance and energy consumption.</li><li><strong>Spare parts availability:</strong> fans, fills, nozzles and auxiliaries can be supplied to support uptime.</li></ul>'), 'GRP construction, fill options, fan configuration, and operational benefits of Ensotek cooling towers.', 'Technical image for cooling tower materials and fill options', 'Features of Ensotek cooling towers', 'GRP construction, fill options, fan configuration, and operational benefits of Ensotek cooling towers.', 'ensotek, grp, fill options, pvc film fill, pp splash fill, energy saving', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- open-circuit-cooling-tower-working-principle
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2606-3333-4333-8333-cccccccc2606', 'cccc2606-1111-4111-8111-cccccccc2606', 'en', 'Open-Circuit Cooling Tower Working Principle', 'open-circuit-cooling-tower-working-principle', JSON_OBJECT('html', '<h2>Open-Circuit Cooling Tower Working Principle</h2><h3>What Is an Open-Circuit Cooling Tower?</h3><p>In an open-circuit (open-loop) cooling tower, the process water comes into <strong>direct contact</strong> with air. Most heat rejection is achieved through evaporation, which typically provides high thermal performance. Because the water is exposed to the environment, water quality management (scaling, fouling, biological control) is essential.</p><h3>Core Heat-Rejection Mechanisms</h3><ul><li><strong>Sensible heat transfer:</strong> heat moves from water to air due to temperature difference.</li><li><strong>Latent heat (evaporation):</strong> a small portion of water evaporates and removes additional heat via phase change.</li></ul><h3>Counterflow vs. Crossflow Arrangements</h3><p><strong>Counterflow</strong>: air rises while water falls. <strong>Crossflow</strong>: air moves horizontally/diagonally across the falling water.</p><h3>Induced-Draft Counterflow: Step-by-Step</h3><ol><li><strong>Hot water enters</strong> the distribution header.</li><li><strong>Nozzles distribute</strong> water evenly over the fill.</li><li><strong>Fill increases surface area</strong> by creating films and droplets.</li><li><strong>Fan induces airflow</strong> through louvers and across the fill zone.</li><li><strong>Heat is rejected</strong>: water cools; a fraction evaporates.</li><li><strong>Cooled water collects</strong> in the cold-water basin.</li><li><strong>Moist air discharges</strong> through the fan stack; cooled water recirculates back to the process.</li></ol><h3>Key Components</h3><ul><li><strong>Structure & basin</strong></li><li><strong>Water distribution & nozzles</strong></li><li><strong>Fill media</strong> (film or splash)</li><li><strong>Fan & motor</strong></li><li><strong>Drift eliminators</strong> to reduce droplet carryover</li><li><strong>Louvers</strong> for airflow control</li></ul><h3>Performance Terms</h3><ul><li><strong>Range:</strong> T<sub>in</sub> − T<sub>out</sub>.</li><li><strong>Approach:</strong> T<sub>out</sub> − T<sub>wb</sub>.</li><li><strong>Wet-bulb:</strong> dominant climate parameter for tower capacity.</li></ul><h3>Water Losses</h3><ul><li><strong>Evaporation</strong></li><li><strong>Drift</strong></li><li><strong>Blowdown</strong></li></ul><h3>Summary</h3><p>Open-circuit towers cool by direct contact and partial evaporation. With proper design and operation, high performance is achievable while controlling water losses via drift elimination and blowdown strategy.</p>'), 'Expanded technical description: operation steps, components, performance metrics, and water losses in open-circuit cooling towers.', 'Open-circuit cooling tower working principle diagram', 'Open-Circuit Cooling Tower Working Principle', 'Expanded technical description: operation steps, components, performance metrics, and water losses in open-circuit cooling towers.', 'open circuit, open loop, counterflow, induced draft, drift, blowdown', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- closed-circuit-cooling-tower-working-principle
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2607-3333-4333-8333-cccccccc2607', 'cccc2607-1111-4111-8111-cccccccc2607', 'en', 'Closed-Circuit Cooling Tower Working Principle', 'closed-circuit-cooling-tower-working-principle', JSON_OBJECT('html', '<h2>Closed-Circuit Cooling Tower Working Principle</h2><h3>What Is a Closed-Circuit Cooling Tower?</h3><p>Closed-circuit (closed-loop) cooling towers are used when the process fluid must remain clean and isolated from ambient air. The process fluid circulates inside a <strong>metal coil (heat exchanger)</strong>. Airflow and a spray-water loop remove heat from the coil surface, cooling the internal process fluid <strong>indirectly</strong>.</p><h3>How It Works (Step-by-Step)</h3><ol><li><strong>Hot process fluid enters the coil</strong> and flows through the heat-exchanger tubes.</li><li><strong>Airflow is induced</strong> by the fan and passes over the coil surface.</li><li><strong>Spray-water loop operates:</strong> recirculating water is pumped to nozzles and sprayed over the coil.</li><li><strong>Heat transfer occurs:</strong> heat moves from the process fluid to the tube wall and then to spray water and air.</li><li><strong>Cooled process fluid returns</strong> to the process while spray water returns to the basin.</li></ol><h3>Does Evaporation Occur?</h3><p>Evaporation does not occur in the closed process loop because the process fluid is contained inside the coil. However, the <strong>spray-water loop</strong> is exposed to air, so some evaporation occurs there and contributes to heat rejection.</p><h3>Free Cooling (Dry Cooler) Mode</h3><p>In cold weather, the tower can often be operated with the spray-water system turned off, using air-only heat rejection—similar to a <strong>dry cooler</strong>. This is commonly called <strong>free cooling</strong> and can reduce energy consumption under favorable ambient conditions.</p><h3>Freeze Risk and Protection Measures</h3><p>If the system is stopped in winter conditions, fluid inside the coil may freeze and damage tubes. Common mitigation strategies include:</p><ul><li><strong>Draining the coil</strong> during shutdown periods.</li><li><strong>Low-flow circulation</strong> to keep fluid moving.</li><li><strong>Glycol/antifreeze</strong> to lower freezing point.</li><li><strong>Control logic</strong> (fan staging, bypass, setpoints) to prevent coil icing.</li></ul><h3>Energy Consumption</h3><p>Electrical consumption is mainly driven by the <strong>fan</strong> and the <strong>spray-water pump</strong>. Optimized equipment selection and controls can improve operating cost depending on climate, load profile, and required approach.</p><h3>Where It Is Used / Key Benefits</h3><ul><li><strong>Clean process fluid:</strong> ideal for sensitive processes and equipment.</li><li><strong>Reduced contamination risk:</strong> process loop is isolated from ambient air.</li><li><strong>Seasonal efficiency:</strong> free cooling opportunities in cooler climates.</li><li><strong>Stable operation:</strong> controlled process-side water quality.</li></ul><h3>Summary</h3><p>Closed-circuit towers cool process fluids indirectly through a coil using airflow and spray water. Evaporation occurs on the spray-water side, not in the process loop. Free cooling can reduce energy use in cold seasons, while freeze protection measures (drain, circulation, glycol, controls) are critical for winter reliability.</p>'), 'Indirect cooling via coil heat exchanger, spray-water evaporation, free cooling operation, freeze protection and fan/pump energy drivers.', 'Closed-circuit cooling tower working principle diagram', 'Closed-Circuit Cooling Tower Working Principle', 'Indirect cooling via coil heat exchanger, spray-water evaporation, free cooling operation, freeze protection and fan/pump energy drivers.', 'closed circuit, closed loop, coil, heat exchanger, spray water, free cooling, freeze', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- required-data-for-cooling-tower-selection
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2608-3333-4333-8333-cccccccc2608', 'cccc2608-1111-4111-8111-cccccccc2608', 'en', 'Required Data for Cooling Tower Selection', 'required-data-for-cooling-tower-selection', JSON_OBJECT('html', '<h2>Required Data for Cooling Tower Selection</h2><p>Cooling towers are typically selected for the <strong>hottest design summer conditions</strong> unless stated otherwise. Accurate selection requires combining process duty, climate conditions, and site constraints. The clearer the inputs, the more reliable and economical the tower sizing will be.</p><h3>1) Process Inputs (Mandatory)</h3><ul><li><strong>Circulating water flow rate</strong>: m³/h (preferred) or heat duty (kW, kcal/h)</li><li><strong>Hot water inlet temperature</strong>: T<sub>in</sub> (°C)</li><li><strong>Cold water outlet temperature</strong>: T<sub>out</sub> (°C)</li><li><strong>Operating profile</strong>: continuous vs. intermittent; constant vs. variable load</li></ul><h3>2) Climate Data (Design Condition)</h3><p>Tower capacity is strongly driven by <strong>wet-bulb temperature</strong>, which represents the practical cooling limit for evaporative systems.</p><ul><li><strong>Wet-bulb temperature (°C)</strong> – mandatory</li><li><strong>Dry-bulb temperature (°C)</strong> – recommended</li><li><strong>Relative humidity (%)</strong> – recommended</li><li><strong>Altitude / barometric pressure</strong> – important at high elevations</li></ul><h3>3) Key Concepts: Range and Approach</h3><p><strong>Range</strong> is the temperature drop across the tower: <code>Range = T<sub>in</sub> − T<sub>out</sub></code>.</p><p><strong>Approach</strong> is the difference between cold water temperature and wet-bulb: <code>Approach = T<sub>out</sub> − T<sub>wb</sub></code>. Lower approach usually means a larger tower and higher cost.</p><h3>4) Water Quality and Fouling Factors</h3><p>Selection is not only thermal. Water quality and fouling potential affect fill/nozzle configuration and maintenance needs.</p><ul><li><strong>Water analysis</strong>: conductivity, hardness, pH, total suspended solids (TSS)</li><li><strong>Contamination sources</strong>: oil, scale, solids, biological growth</li><li><strong>Water treatment</strong>: inhibitors, biocides, pH control</li><li><strong>Blowdown strategy</strong> to control cycles of concentration</li></ul><h3>5) Mechanical and Site Constraints</h3><ul><li><strong>Location and airflow</strong>: risk of recirculation, obstructions, intake/exhaust clearance</li><li><strong>Footprint limits</strong>: length/width/height constraints and service access</li><li><strong>Noise limit</strong>: sensitive sites may require low-noise options</li><li><strong>Electrical</strong>: supply and VFD requirement</li><li><strong>Freeze risk</strong>: winter operation plan (heaters, glycol, controls)</li></ul><h3>Example Input Set</h3><p>Example: Flow 120 m³/h, T<sub>in</sub>=40°C, T<sub>out</sub>=30°C, wet-bulb=24°C, altitude 200 m, continuous operation, moderately fouling water.</p><h3>Summary</h3><p>Provide flow and temperatures, wet-bulb design, water quality, and site constraints together. With complete inputs, tower type and configuration (open/closed circuit, fill, fan/pump, controls) can be selected reliably.</p>'), 'Checklist for cooling tower selection: flow and temperatures, wet-bulb design, range/approach, water quality, blowdown strategy, and site constraints.', 'Cooling tower selection inputs – checklist', 'Required data for cooling tower selection', 'Checklist for cooling tower selection: flow and temperatures, wet-bulb design, range/approach, water quality, blowdown strategy, and site constraints.', 'cooling tower selection, tower sizing, design inputs, flow rate, wet-bulb, range, approach, water quality, blowdown', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- turkey-summer-design-dry-wet-bulb-values
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2609-3333-4333-8333-cccccccc2609', 'cccc2609-1111-4111-8111-cccccccc2609', 'en', 'Turkey Summer Design Dry-Bulb and Wet-Bulb Values', 'turkey-summer-design-dry-wet-bulb-values', JSON_OBJECT('html', '<p>This table provides typical <strong>summer design</strong> dry-bulb and wet-bulb temperatures by province in Turkey. It can be used as a practical reference for <strong>cooling tower selection</strong>, condenser loop design, and general HVAC engineering calculations.</p><p><strong>Note:</strong> Values represent typical design conditions commonly referenced from national meteorological datasets. For project-critical sizing, consider validating against the latest published climate normals and/or local measurements.</p><table border="1" cellpadding="4" cellspacing="0"><thead><tr><th>City / Province</th><th>Dry-Bulb (°C)</th><th>Wet-Bulb (°C)</th></tr></thead><tbody><tr><td>Adana</td><td>38</td><td>27</td></tr><tr><td>Adıyaman</td><td>38</td><td>23</td></tr><tr><td>Afyon</td><td>34</td><td>21</td></tr><tr><td>Ağrı</td><td>34</td><td>25</td></tr><tr><td>Aksaray</td><td>34</td><td>20</td></tr><tr><td>Amasya</td><td>31</td><td>21</td></tr><tr><td>Ankara</td><td>35</td><td>20</td></tr><tr><td>Antalya</td><td>39</td><td>28</td></tr><tr><td>Artvin</td><td>30</td><td>26</td></tr><tr><td>Aydın</td><td>39</td><td>24</td></tr><tr><td>Balıkesir</td><td>38</td><td>25</td></tr><tr><td>Bayburt</td><td>33</td><td>23</td></tr><tr><td>Bilecik</td><td>34</td><td>23</td></tr><tr><td>Bingöl</td><td>33</td><td>21</td></tr><tr><td>Bitlis</td><td>34</td><td>22</td></tr><tr><td>Bolu</td><td>34</td><td>23</td></tr><tr><td>Burdur</td><td>36</td><td>21</td></tr><tr><td>Bursa</td><td>37</td><td>25</td></tr><tr><td>Çanakkale</td><td>34</td><td>25</td></tr><tr><td>Çankırı</td><td>34</td><td>23</td></tr><tr><td>Çorum</td><td>29</td><td>22</td></tr><tr><td>Denizli</td><td>38</td><td>24</td></tr><tr><td>Diyarbakır</td><td>42</td><td>23</td></tr><tr><td>Düzce</td><td>34</td><td>24</td></tr><tr><td>Edirne</td><td>36</td><td>25</td></tr><tr><td>Elazığ</td><td>38</td><td>21</td></tr><tr><td>Erzincan</td><td>36</td><td>22</td></tr><tr><td>Erzurum</td><td>31</td><td>19</td></tr><tr><td>Eskişehir</td><td>34</td><td>22</td></tr><tr><td>Gaziantep</td><td>39</td><td>23</td></tr><tr><td>Giresun</td><td>29</td><td>25</td></tr><tr><td>Gümüşhane</td><td>33</td><td>23</td></tr><tr><td>Hakkari</td><td>34</td><td>20</td></tr><tr><td>Hatay</td><td>37</td><td>28</td></tr><tr><td>İskenderun</td><td>37</td><td>29</td></tr><tr><td>Isparta</td><td>34</td><td>21</td></tr><tr><td>Iğdır</td><td>33</td><td>22</td></tr><tr><td>İçel (Mersin)</td><td>35</td><td>29</td></tr><tr><td>İstanbul</td><td>33</td><td>24</td></tr><tr><td>İzmir</td><td>37</td><td>24</td></tr><tr><td>Karabük</td><td>32</td><td>25</td></tr><tr><td>Karaman</td><td>34</td><td>21</td></tr><tr><td>Kars</td><td>30</td><td>20</td></tr><tr><td>Kastamonu</td><td>34</td><td>22</td></tr><tr><td>Kayseri</td><td>36</td><td>23</td></tr><tr><td>Kırıkkale</td><td>35</td><td>21</td></tr><tr><td>Kırklareli</td><td>35</td><td>24</td></tr><tr><td>Kırşehir</td><td>35</td><td>21</td></tr><tr><td>Kilis</td><td>39</td><td>23</td></tr><tr><td>Kocaeli</td><td>36</td><td>25</td></tr><tr><td>Konya</td><td>34</td><td>21</td></tr><tr><td>Kütahya</td><td>33</td><td>21</td></tr><tr><td>Malatya</td><td>38</td><td>21</td></tr><tr><td>Manisa</td><td>40</td><td>25</td></tr><tr><td>Kahramanmaraş</td><td>36</td><td>25</td></tr><tr><td>Mardin</td><td>38</td><td>23</td></tr><tr><td>Muğla</td><td>37</td><td>22</td></tr><tr><td>Muş</td><td>32</td><td>20</td></tr><tr><td>Nevşehir</td><td>28</td><td>21</td></tr><tr><td>Niğde</td><td>34</td><td>20</td></tr><tr><td>Ordu</td><td>30</td><td>23</td></tr><tr><td>Osmaniye</td><td>38</td><td>26</td></tr><tr><td>Rize</td><td>30</td><td>26</td></tr><tr><td>Sakarya</td><td>35</td><td>25</td></tr><tr><td>Samsun</td><td>32</td><td>25</td></tr><tr><td>Siirt</td><td>40</td><td>23</td></tr><tr><td>Sinop</td><td>30</td><td>25</td></tr><tr><td>Sivas</td><td>33</td><td>20</td></tr><tr><td>Şırnak</td><td>38</td><td>21</td></tr><tr><td>Şanlıurfa</td><td>43</td><td>24</td></tr><tr><td>Tekirdağ</td><td>33</td><td>25</td></tr><tr><td>Tokat</td><td>29</td><td>20</td></tr><tr><td>Trabzon</td><td>31</td><td>25</td></tr><tr><td>Tunceli</td><td>37</td><td>22</td></tr><tr><td>Uşak</td><td>35</td><td>22</td></tr><tr><td>Van</td><td>33</td><td>20</td></tr><tr><td>Yalova</td><td>33</td><td>24</td></tr><tr><td>Yozgat</td><td>32</td><td>20</td></tr><tr><td>Zonguldak</td><td>32</td><td>25</td></tr></tbody></table><p><em>Source: Turkish State Meteorological Service (MGM)</em></p>'), 'Reference table listing typical summer design dry-bulb and wet-bulb temperatures for provinces in Turkey. Intended for cooling tower selection and HVAC engineering calculations.', 'Turkey summer design dry-bulb and wet-bulb values', 'Turkey Summer Design Dry-Bulb and Wet-Bulb Values', 'Reference table listing typical summer design dry-bulb and wet-bulb temperatures for provinces in Turkey. Intended for cooling tower selection and HVAC engineering calculations.', 'design, summer, dry-bulb, wet-bulb, turkey, climate data, hvac, cooling tower', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
