-- cooling-tower-selection-guide
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2601-3333-4333-8333-cccccccc2601', 'cccc2601-1111-4111-8111-cccccccc2601', 'en', 'Cooling Tower Selection Guide', 'cooling-tower-selection-guide', JSON_OBJECT('html', '<p>Selecting a cooling tower is not completed by a capacity calculation alone. Process water temperatures, the wet-bulb value, approach temperature, site layout, noise limits, water quality and maintenance access must be evaluated together.</p><h2>Key selection criteria</h2><p>Open-circuit towers offer high evaporative efficiency and an economical initial investment. Closed-circuit towers separate the process fluid from the outside environment and reduce the risk of contamination. Hybrid solutions are considered by facilities that want a finer balance between water consumption, visible plume and energy cost.</p><h2>Why do project data matter?</h2><p>When flow rate, inlet and outlet temperatures, wet-bulb value, altitude and operating regime are not specified correctly, the tower capacity may fail to deliver the performance expected on site. The Ensotek engineering team analyses thermal selection, material structure and the maintenance scenario together using these data.</p>'), 'Evaluate open-circuit, closed-circuit and hybrid cooling tower options against process load, water quality, approach temperature and site conditions.', NULL, 'Cooling Tower Selection Guide | Ensotek', 'Capacity, approach temperature, water quality, maintenance and energy efficiency criteria for selecting a cooling tower for industrial facilities.', 'cooling tower selection,open circuit,closed circuit,hybrid cooling tower', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- legionella-prevention-in-cooling-towers
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2602-3333-4333-8333-cccccccc2602', 'cccc2602-1111-4111-8111-cccccccc2602', 'en', 'Legionella Prevention in Cooling Towers', 'legionella-prevention-in-cooling-towers', JSON_OBJECT('html', '<p>When cooling towers are not operated correctly, biofilm formation, sediment build-up and stagnant water zones can increase microbiological risks. Legionella management is therefore not a one-off cleaning but a discipline of regular monitoring and documented maintenance.</p><h2>Preventive maintenance approach</h2><p>Regular blowdown, filtration, water treatment, biocide dosing and mechanical cleaning must be applied together. Drift eliminators, fill, the basin and the water distribution system should be inspected periodically.</p><h2>Monitoring and records</h2><p>When temperature, conductivity, pH, biocide level and microbiological analysis results are recorded, risky trends are noticed early. The Ensotek service approach arranges the maintenance plan according to the facility''s operating regime.</p>'), 'Reducing Legionella risk requires water treatment, biocide application, regular cleaning and maintenance records to be carried out together.', NULL, 'Legionella Prevention in Cooling Towers | Ensotek', 'Maintenance, cleaning, water treatment and monitoring practices to reduce Legionella risk in cooling towers.', 'legionella,cooling tower maintenance,water treatment,biocide', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

-- grp-frp-cooling-tower-shells-compared
INSERT INTO `custom_pages_i18n` (`id`,`page_id`,`locale`,`title`,`slug`,`content`,`summary`,`featured_image_alt`,`meta_title`,`meta_description`,`tags`,`created_at`,`updated_at`) VALUES
('cccc2603-3333-4333-8333-cccccccc2603', 'cccc2603-1111-4111-8111-cccccccc2603', 'en', 'GRP and FRP Cooling Tower Shells Compared', 'grp-frp-cooling-tower-shells-compared', JSON_OBJECT('html', '<p>The terms GRP (CTP) and FRP refer to glass-fibre-reinforced polyester composite structures. In cooling tower shells this material group is widely used because of its corrosion resistance and low maintenance requirement.</p><h2>Why a composite shell?</h2><p>On metal surfaces, corrosion, repainting and the effect of the chemical environment can create significant operating costs. GRP/FRP shells are light, modular and resistant to chemical attack, which simplifies site assembly and long-term operation.</p><h2>What to consider in selection</h2><p>Resin type, UV resistance, joint details, service access and the design of the load-bearing structure determine shell performance. In its tower designs, Ensotek combines its composite manufacturing experience with thermal design and maintenance access.</p>'), 'GRP/FRP shells are a strong alternative in industrial cooling towers thanks to corrosion resistance, low maintenance and long service life.', NULL, 'GRP and FRP Cooling Tower Shell Comparison | Ensotek', 'Advantages of GRP and FRP cooling tower shells in terms of corrosion, maintenance, weight and service life.', 'GRP,FRP,cooling tower shell,composite', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `content`=VALUES(`content`), `summary`=VALUES(`summary`), `featured_image_alt`=VALUES(`featured_image_alt`), `meta_title`=VALUES(`meta_title`), `meta_description`=VALUES(`meta_description`), `tags`=VALUES(`tags`), `updated_at`=CURRENT_TIMESTAMP(3);

